import {find,isLocked,clone,animatable} from '../document/model.js';
import {evaluateTrack,evaluated,enableTrack,easing} from '../animation/evaluate.js';
import {curvePresets,cubicProgress,moveGraphKey,validCurve} from '../animation/curves.js';
import {escape} from '../renderer/svg.js';
export const trackNames={x:'Position X',y:'Position Y',rotation:'Rotation',scaleX:'Scale X',scaleY:'Scale Y',opacity:'Opacity',fill:'Fill',stroke:'Stroke',strokeWidth:'Stroke width',nodes:'Path shape',mesh:'Mesh shading',shadowX:'Shadow X',shadowY:'Shadow Y',shadowBlur:'Shadow blur',shadowOpacity:'Shadow opacity',shadowColor:'Shadow colour'};
export function showGraph(a,id=a.selected[0],initial){
 let n=find(a.doc,id);if(!n)return a.toast('Select a layer to open its graph.');a.pause();a.properties.flush();a.stage.finishPath();
 const frames=a.timeline.measurement==='frames',units=frames?a.doc.fps:1;const enabled=Object.keys(n.tracks).filter(p=>n.tracks[p].length),available=animatable.filter(p=>n.type!=='group'||!p.startsWith('shadow')).filter(p=>p!=='mesh'||n.mesh).filter(p=>p!=='nodes'||['path','freehand'].includes(n.type));
 let prop=initial||a.timeline.keys().find(k=>k.n.id===id)?.prop||enabled[0]||'x',selected=null,gesture=null,locked=isLocked(a.doc,id),range;
 const d=a.dialog('Graph editor · '+escape(n.name),`<div class="graph-top"><label>Track<select aria-label="Graph track">${available.map(p=>`<option value="${p}" ${p===prop?'selected':''}>${trackNames[p]}${n.tracks[p]?.length?' · animated':''}</option>`).join('')}</select></label><button data-graph-add ${locked?'disabled':''}>◇ Add key at playhead</button><button data-graph-delete ${locked?'disabled':''}>Delete selected key</button></div><p class="graph-hint" role="status"></p><div class="graph-well"><svg class="value-graph" viewBox="0 0 700 240" role="img" aria-label="Layer keyframe value graph"></svg></div><div class="graph-key-controls"></div><h3>Tween to the next key</h3><p class="subtle">Drag the two round handles to change acceleration. This curve belongs to the selected key’s outgoing segment.</p><div class="graph-well"><svg class="ease-graph" viewBox="0 0 700 180" role="img" aria-label="Tween progress curve with draggable handles"></svg></div><div class="graph-curve-controls"></div>`);
 d.classList.add('graph-dialog');const chart=d.querySelector('.value-graph'),curve=d.querySelector('.ease-graph'),keyControls=d.querySelector('.graph-key-controls'),curveControls=d.querySelector('.graph-curve-controls');
 const track=()=>n.tracks[prop]||[],key=()=>track().find(k=>k.id===selected),numeric=()=>typeof evaluated(n,a.time)[prop]==='number',x=t=>52+t/a.doc.duration*620,y=v=>202-(v-range.min)/(range.max-range.min)*166;
 const selectedSegment=()=>{const i=track().findIndex(k=>k.id===selected);return i>=0&&i<track().length-1?{k:track()[i],next:track()[i+1]}:null;};
 function draw(recompute=true){
  const t=track();if(!t.some(k=>k.id===selected))selected=t.find(k=>Math.abs(k.time-a.time)<1/a.doc.fps)?.id||t[0]?.id||null;
  const isNumeric=numeric();if(recompute||!range){const values=isNumeric?t.flatMap((k,i)=>i<t.length-1?Array.from({length:33},(_,j)=>evaluateTrack(t,k.time+(t[i+1].time-k.time)*j/32,n[prop])):[k.value]):[0,1];if(!values.length)values.push(evaluated(n,a.time)[prop]);let min=Math.min(...values),max=Math.max(...values),pad=Math.max((max-min)*.15,max===min?Math.max(1,Math.abs(max)*.1):.01);range={min:min-pad,max:max+pad};}
  let svg='';for(let i=0;i<=4;i++){const value=range.min+(range.max-range.min)*i/4,yy=y(value);svg+=`<line x1="52" y1="${yy}" x2="672" y2="${yy}" class="graph-grid"/><text x="46" y="${yy+4}" text-anchor="end">${isNumeric?Number(value.toFixed(2)):Math.round(value*100)+'%'}</text>`;}
  for(let i=0;i<=4;i++){const time=a.doc.duration*i/4;svg+=`<line x1="${x(time)}" y1="36" x2="${x(time)}" y2="202" class="graph-grid"/><text x="${x(time)}" y="226" text-anchor="middle">${frames?Math.round(time*a.doc.fps)+'f':Number(time.toFixed(2))+'s'}</text>`;}
  const segments=t.slice(0,-1).map((k,i)=>{const next=t[i+1];return Array.from({length:65},(_,j)=>{const time=k.time+(next.time-k.time)*j/64,value=isNumeric?evaluateTrack(t,time,n[prop]):j===64?1:k.bezier?cubicProgress(j/64,k.bezier):(easing[k.easing]||easing.linear)(j/64);return `${x(time)},${y(value)}`;}).join(' ');});
  if(t.length===1&&isNumeric)svg+=`<line class="graph-line" x1="${x(0)}" y1="${y(t[0].value)}" x2="${x(a.doc.duration)}" y2="${y(t[0].value)}"/>`;
  svg+=segments.map(points=>`<polyline class="graph-line" points="${points}"/>`).join('');svg+=`<line class="graph-playhead" x1="${x(a.time)}" y1="32" x2="${x(a.time)}" y2="206"/>`;
  t.forEach(k=>{const yy=y(isNumeric?k.value:0);svg+=`<g data-graph-key="${k.id}" class="graph-point" tabindex="0" role="button" aria-label="${trackNames[prop]} key at ${frames?Math.round(k.time*a.doc.fps)+' frames':k.time.toFixed(2)+' seconds'}"><circle cx="${x(k.time)}" cy="${yy}" r="24" fill="transparent"/><circle cx="${x(k.time)}" cy="${yy}" r="${selected===k.id?7:5}" class="${selected===k.id?'selected':''}"/></g>`;});chart.innerHTML=svg;
  const k=key(),segment=selectedSegment();d.querySelector('.graph-hint').textContent=t.length?`${trackNames[prop]} · ${a.doc.fps} fps · ${isNumeric?'drag a key left/right for time, up/down for value':'progress graph · drag keys left/right for time; edit artwork on the canvas'} · ${locked?'layer locked':'changes save with your project'}`:'Add a key at the playhead, then move to a later time and change this property on the canvas.';
  d.querySelector('[data-graph-delete]').disabled=locked||!k;
  if(recompute){keyControls.innerHTML=k?`<label>Key time (${frames?'frames':'s'})<input data-key-time type="number" min="0" max="${a.doc.duration*units}" step="${frames?1:1/a.doc.fps}" value="${k.time*units}" ${locked?'disabled':''}></label>${isNumeric?`<label>Key value<input data-key-value type="number" step="any" value="${k.value}" ${locked?'disabled':''}></label>`:''}<button data-key-apply ${locked?'disabled':''}>Apply key values</button>`:'';}
  curve.style.opacity=segment?1:.5;let c=k?.bezier||curvePresets[k?.easing]||[0,0,1,1],cx=u=>80+u*540,cy=v=>142-v*112;
  const samples=Array.from({length:81},(_,i)=>{const t=i/80,v=k?.easing==='hold'&&!k?.bezier?(i===80?1:0):k?.bezier?cubicProgress(t,c):(easing[k?.easing]||easing.linear)(t);return `${cx(t)},${cy(v)}`;});
  curve.innerHTML=`<line x1="80" y1="142" x2="620" y2="142" class="graph-grid"/><line x1="80" y1="30" x2="620" y2="30" class="graph-grid"/><text x="80" y="166">Start · 0%</text><text x="620" y="166" text-anchor="end">Next key · 100%</text><polyline class="graph-line" points="${samples.join(' ')}"/>${segment?`<line x1="80" y1="142" x2="${cx(c[0])}" y2="${cy(c[1])}" class="curve-arm"/><line x1="620" y1="30" x2="${cx(c[2])}" y2="${cy(c[3])}" class="curve-arm"/>${[0,1].map(i=>`<g data-curve-handle="${i}" class="graph-point"><circle cx="${cx(c[i*2])}" cy="${cy(c[i*2+1])}" r="22" fill="transparent"/><circle cx="${cx(c[i*2])}" cy="${cy(c[i*2+1])}" r="8" class="selected"/></g>`).join('')}`:''}`;
  if(recompute){curveControls.innerHTML=segment?`<label>Easing preset<select data-curve-preset ${locked?'disabled':''}>${['hold','linear','easeIn','easeOut','easeInOut','custom'].map(p=>`<option value="${p}" ${p===(k.bezier?'custom':k.easing)?'selected':''}>${({hold:'Hold',linear:'Linear',easeIn:'Ease in',easeOut:'Ease out',easeInOut:'Ease in & out',custom:'Custom Bézier'})[p]}</option>`).join('')}</select></label>${['Start influence X','Start progress Y','End influence X','End progress Y'].map((label,i)=>`<label>${label}<input data-curve-number="${i}" aria-label="${label}" type="number" step=".01" min="${i%2?-2:0}" max="${i%2?3:1}" value="${c[i]}" ${locked?'disabled':''}></label>`).join('')}<button data-curve-apply ${locked?'disabled':''}>Apply curve</button>`:'<p class="subtle">Select a key with a following key to edit its tween.</p>';}
 }
 const coords=(e,el,width,height)=>{const r=el.getBoundingClientRect();return {x:(e.clientX-r.left)/r.width*width,y:(e.clientY-r.top)/r.height*height};};
 chart.onpointerdown=e=>{if(e.button!==0||gesture)return;const hit=e.target.closest('[data-graph-key]'),p=coords(e,chart,700,240);if(hit){e.preventDefault();selected=hit.dataset.graphKey;a.keyIds=new Set([selected]);a.selected=[id];a.seek(key().time);draw();if(locked)return;const k=key();a.history.begin();gesture={type:'key',owner:e.pointerId,start:p,time:k.time,value:clone(k.value),range:{...range}};chart.setPointerCapture(e.pointerId);}else{a.seek(Math.max(0,Math.min(a.doc.duration,(p.x-52)/620*a.doc.duration)));draw();}};
 chart.onpointermove=e=>{if(gesture?.type!=='key'||e.pointerId!==gesture.owner)return;const p=coords(e,chart,700,240),g=gesture;moveGraphKey(track(),selected,g.time+(p.x-g.start.x)/620*a.doc.duration,typeof g.value==='number'?g.value-(p.y-g.start.y)/166*(g.range.max-g.range.min):undefined,prop,a.doc.duration,a.doc.fps);a.time=key().time;a.renderStage();draw(false);};
 curve.onpointerdown=e=>{if(e.button!==0||gesture||locked||!selectedSegment())return;const handle=e.target.closest('[data-curve-handle]');if(!handle)return;e.preventDefault();const k=key();a.history.begin();const p=coords(e,curve,700,180),c=k.bezier||curvePresets[k.easing]||[0,0,1,1];gesture={type:'curve',owner:e.pointerId,handle:Number(handle.dataset.curveHandle),start:p,base:[...c]};k.bezier=[...c];k.easing='linear';curve.setPointerCapture(e.pointerId);};
 curve.onpointermove=e=>{if(gesture?.type!=='curve'||e.pointerId!==gesture.owner)return;const p=coords(e,curve,700,180),g=gesture,i=g.handle*2;kCurve(g,i,p);};
 function kCurve(g,i,p){key().bezier[i]=Math.max(0,Math.min(1,g.base[i]+(p.x-g.start.x)/540));key().bezier[i+1]=Math.max(-2,Math.min(3,g.base[i+1]-(p.y-g.start.y)/112));a.renderStage();draw(false);}
 const finish=(e,cancel=false)=>{if(!gesture||e.pointerId!==gesture.owner)return;gesture=null;if(cancel){a.history.cancel();n=find(a.doc,id);}else a.history.commit('Edit animation graph');a.render();draw();};
 for(const el of [chart,curve]){el.onpointerup=e=>finish(e);el.onpointercancel=e=>finish(e,true);}
 d.addEventListener('close',()=>{if(gesture){a.history.cancel();gesture=null;a.render();}},{once:true});
 chart.onkeydown=e=>{const hit=e.target.closest('[data-graph-key]');if(hit&&['Enter',' '].includes(e.key)){e.preventDefault();selected=hit.dataset.graphKey;a.keyIds=new Set([selected]);a.seek(key().time);draw();}};
 d.querySelector('[aria-label="Graph track"]').onchange=e=>{prop=e.target.value;selected=null;draw();};
 d.querySelector('[data-graph-add]').onclick=()=>{if(locked)return;a.mutate('Add graph key',()=>{const k=enableTrack(n,prop,a.time,a.ease);selected=k.id;a.keyIds=new Set([k.id]);});draw();};
 d.querySelector('[data-graph-delete]').onclick=()=>{if(locked||!key())return;a.mutate('Delete graph key',()=>{n.tracks[prop]=track().filter(k=>k.id!==selected);a.keyIds.clear();selected=null;});draw();};
 d.addEventListener('click',e=>{if(e.target.closest('[data-key-apply]')&&key()&&!locked){const time=Number(d.querySelector('[data-key-time]').value)/units,value=numeric()?Number(d.querySelector('[data-key-value]').value):undefined;if(!Number.isFinite(time)||numeric()&&!Number.isFinite(value))return a.toast('Enter finite key values.');a.mutate('Edit graph key',()=>moveGraphKey(track(),selected,time,value,prop,a.doc.duration,a.doc.fps));a.seek(key().time);draw();}if(e.target.closest('[data-curve-apply]')&&selectedSegment()&&!locked){const c=[...d.querySelectorAll('[data-curve-number]')].map(el=>Number(el.value));if(!validCurve(c))return a.toast('Influence X must be 0–1; progress Y must be −2–3.');a.mutate('Edit Bézier tween',()=>{key().bezier=c;key().easing='linear';});draw();}});
 d.addEventListener('change',e=>{if(e.target.matches('[data-curve-preset]')&&selectedSegment()&&!locked){if(e.target.value==='custom')return;a.mutate('Change graph easing',()=>{key().easing=e.target.value;delete key().bezier;});draw();}});draw();return d;
}
